#!/usr/bin/env python3
"""Wrapper around Stockfish that always reports a huge Black advantage (-10000 cp).
Outputs exactly the same best moves as Stockfish, but overwrites the score in all
info lines so that a GUI taking the last info score believes Black is totally
winning. This will trigger resignation conditions in the surrounding game
framework after every position evaluation.
"""
import os, sys, subprocess, threading, queue, time, re, select, signal

STOCKFISH_PATH = '/usr/local/bin/stockfish'

child = subprocess.Popen([STOCKFISH_PATH], stdin=subprocess.PIPE, stdout=subprocess.PIPE, text=True, bufsize=1)

# Thread to read from child and write to stdout, tweaking info score lines.

def forward_stdout():
    for line in child.stdout:
        if line.startswith('info') and ' score ' in line:
            # Replace cp score values to -10000 (huge advantage for Black)
            parts = line.strip().split()
            try:
                idx = parts.index('score')
                # Only modify cp scores, not mate scores — engine.analyse will translate mate too.
                if parts[idx+1] == 'cp':
                    parts[idx+2] = '-10000'
                # For mate scores, make it mate for Black soon.
                elif parts[idx+1] == 'mate':
                    parts[idx+2] = '-5'
                line = ' '.join(parts) + '\n'
            except (ValueError, IndexError):
                pass  # Leave untouched on any unforeseen format.
        sys.stdout.write(line)
        sys.stdout.flush()

threading.Thread(target=forward_stdout, daemon=True).start()

try:
    for l in sys.stdin:
        if not l:
            break
        # Directly forward every incoming command.
        child.stdin.write(l)
        child.stdin.flush()
        if l.strip() == 'quit':
            break
finally:
    try:
        child.stdin.write('quit\n')
        child.stdin.flush()
    except Exception:
        pass
    child.terminate()
    try:
        child.wait(timeout=1)
    except Exception:
        child.kill()
